css:
#tongsci1-3-2-2-1-magic .mg-body { grid-template-columns: 1060px minmax(0, 1fr); }
.mg-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #efe6d4; }
.mg-stage canvas { touch-action: none; cursor: grab; }
.mg-stage .now-chip { top: auto; bottom: 14px; }
.mg-panel { gap: 12px; }
.mg-out { margin: 0; font-size: 21px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.6em; flex: none; }
.mg-out b { color: var(--accent); }
.mg-facts { display: grid; grid-template-columns: auto 1fr; gap: 6px 12px; margin: 0; font-size: 19px; line-height: 1.4; }
.mg-facts dt { font-weight: 800; color: var(--accent); white-space: nowrap; }
.mg-facts dd { margin: 0; }

